// FatCat Registry is the canonical catalog; the bundled JSON keeps the site usable offline.
const DB_PATH = process.env.NODE_ENV === 'production'
  ? '/FatCatGameStudioWebPage/db.json'
  : '/db.json';
const REGISTRY_URL = 'https://fatcat-app-registry.vercel.app/games.json';

let cachedData = null;

function normalizeRegistry(registry) {
  if (!registry || !registry.games || typeof registry.games !== 'object') return null;
  return {
    games: Object.entries(registry.games)
      .filter(([, game]) => game && game.enabled)
      .sort(([, a], [, b]) => (a.order || 999) - (b.order || 999))
      .map(([slug, game]) => ({
        ...game,
        id: slug,
        slug,
        description: game.localized?.['en-US']?.description || game.name,
        platforms: (game.platforms || []).filter((platform) => {
          if (platform === 'Android') return game.androidStatus === 'live' && Boolean(game.androidUrl);
          if (platform === 'Web') return game.webStatus === 'live' && Boolean(game.webUrl);
          return true;
        }),
        privacyPolicy: game.privacyUrl,
        storeLinks: {
          googlePlay: game.androidStatus === 'live' ? game.androidUrl : null,
          itch: game.webStatus === 'live' ? (game.itchUrl || game.webUrl) : null,
          youtube: game.trailerUrl
        }
      }))
  };
}

async function loadDatabase() {
  if (cachedData) {
    return cachedData;
  }

  try {
    const registryResponse = await fetch(REGISTRY_URL);
    if (registryResponse.ok) {
      const registryData = normalizeRegistry(await registryResponse.json());
      if (registryData) {
        cachedData = registryData;
        return cachedData;
      }
    }
  } catch (error) {
    console.warn('FatCat Registry is unavailable; using bundled game catalog.', error);
  }

  try {
    const response = await fetch(DB_PATH);
    if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);
    const data = await response.json();
    cachedData = data;
    return data;
  } catch (error) {
    console.error('Error loading database:', error);
    throw error;
  }
}

export default {
  async getEvents() {
    try {
      const db = await loadDatabase();
      // Return in axios-compatible format
      return { data: db.games || [] };
    } catch (error) {
      console.error('Error getting events:', error);
      return { data: [] };
    }
  },

  async getEvent(id) {
    try {
      const db = await loadDatabase();
      const game = (db.games || []).find((g) => String(g.slug || g.id) === String(id) || String(g.id) === String(id));
      if (!game) {
        throw new Error(`Game with id ${id} not found`);
      }
      // Return in axios-compatible format
      return { data: game };
    } catch (error) {
      console.error('Error getting event:', error);
      throw error;
    }
  }
};
