const supportedLanguages = new Set(['en', 'es']);

function toSupportedLanguage(value) {
  if (typeof value !== 'string') return null;
  const language = value.trim().toLowerCase().split('-')[0];
  return supportedLanguages.has(language) ? language : null;
}

export function detectSiteLanguage() {
  if (typeof navigator === 'undefined') return 'en';
  const preferences = [
    ...(Array.isArray(navigator.languages) ? navigator.languages : []),
    navigator.language
  ];
  return preferences.map(toSupportedLanguage).find(Boolean) || 'en';
}

export function getInitialSiteLanguage() {
  try {
    const saved = toSupportedLanguage(localStorage.getItem('fatcat-site-language'));
    if (saved) return saved;
  } catch (error) { /* browser storage may be unavailable */ }
  return detectSiteLanguage();
}
