<template>
  <div class="studio-detail">
    <header class="detail-header">
      <div class="detail-shell detail-nav">
        <router-link class="detail-brand" to="/">
          <img src="/FatCatGameStudioWebPage/site-assets/fatcat-symbol.png" alt="" />
          <span>FATCAT<small>GAME STUDIO</small></span>
        </router-link>
        <div class="detail-actions">
          <button type="button" @click="toggleLanguage">{{ language === 'en' ? 'ES' : 'EN' }}</button>
          <router-link to="/">{{ copy.back }}</router-link>
        </div>
      </div>
    </header>

    <main class="detail-shell detail-main">
      <div v-if="loading" class="detail-loading">{{ copy.loading }}</div>
      <section v-else-if="game" class="detail-content">
        <router-link class="detail-back" to="/">← {{ copy.back }}</router-link>
        <div class="detail-hero">
          <div class="detail-cover"><img :src="game.coverUrl || game.iconUrl" :alt="name" /></div>
          <div class="detail-copy">
            <span class="detail-eyebrow">{{ game.genre }} · {{ platforms }}</span>
            <h1>{{ name }}</h1>
            <p class="detail-tagline">{{ localized.tagline || localized.description }}</p>
            <p class="detail-description">{{ localized.overview || localized.description }}</p>
            <div class="detail-links">
              <a v-if="game.androidStatus === 'live' && game.androidUrl" class="detail-button primary" :href="game.androidUrl" target="_blank" rel="noopener noreferrer">{{ copy.googlePlay }} ↗</a>
              <a v-if="game.webStatus === 'live' && game.itchUrl" class="detail-button primary" :href="game.itchUrl" target="_blank" rel="noopener noreferrer">{{ copy.play }} ↗</a>
              <a v-if="game.trailerUrl" class="detail-button" :href="game.trailerUrl" target="_blank" rel="noopener noreferrer">{{ copy.trailer }} ↗</a>
              <router-link v-if="privacyRoute" class="detail-button" :to="privacyRoute">{{ copy.privacy }}</router-link>
            </div>
          </div>
        </div>

        <section v-if="localized.features && localized.features.length" class="detail-features">
          <span class="detail-eyebrow">{{ copy.inside }}</span>
          <h2>{{ copy.features }}</h2>
          <ul>
            <li v-for="feature in localized.features" :key="feature">{{ feature }}</li>
          </ul>
        </section>

        <section v-if="game.screenshots && game.screenshots.length" class="detail-gallery">
          <div class="gallery-heading">
            <div><span class="detail-eyebrow">{{ copy.gallery }}</span><h2>{{ copy.galleryTitle }}</h2></div>
            <p>{{ copy.galleryHelp }}</p>
          </div>
          <div v-if="mediaFilters.length > 1" class="media-filters" role="group" :aria-label="copy.filterMedia">
            <button v-for="filter in mediaFilters" :key="filter.id" type="button" :class="{ active: activeMediaFilter === filter.id }" @click="activeMediaFilter = filter.id">{{ filter.label }}</button>
          </div>
          <div class="gallery-grid">
            <button v-for="media in visibleMedia" :key="media.url" type="button" class="media-card" :class="'media-' + mediaGroup(media)" @click="openMedia(media, $event)" :aria-label="copy.openImage + ': ' + mediaLabel(media)">
              <span class="media-frame" :class="'frame-' + media.kind"><img :src="media.url" :alt="name + ' — ' + mediaLabel(media)" loading="lazy" /></span>
              <span class="media-meta"><span class="media-badge">{{ mediaPlatformLabel(media.platform) }}</span><span class="media-kind">{{ mediaKindLabel(media.kind) }}</span><span class="media-expand" aria-hidden="true">↗</span></span>
            </button>
          </div>
        </section>
      </section>
      <section v-else class="detail-missing">
        <h1>{{ copy.missing }}</h1>
        <router-link class="detail-button primary" to="/">{{ copy.back }}</router-link>
      </section>
    </main>

    <div v-if="selectedMedia" ref="lightbox" class="lightbox" role="dialog" aria-modal="true" :aria-label="copy.openImage" tabindex="-1" @click.self="closeMedia" @touchstart="startPinch" @touchmove.prevent="movePinch" @wheel.prevent="wheelZoom">
      <div class="lightbox-top"><span>{{ mediaLabel(selectedMedia) }}</span><div class="lightbox-controls"><button type="button" :aria-label="copy.zoomOut" @click="zoomBy(-0.25)">−</button><span>{{ Math.round(lightboxZoom * 100) }}%</span><button type="button" :aria-label="copy.zoomIn" @click="zoomBy(0.25)">+</button><button type="button" :aria-label="copy.resetZoom" @click="lightboxZoom = 1">1:1</button><button type="button" class="lightbox-close" :aria-label="copy.closeImage" @click="closeMedia">×</button></div></div>
      <div class="lightbox-stage"><img class="lightbox-image" :src="selectedMedia.url" :alt="name + ' — ' + mediaLabel(selectedMedia)" :style="{ transform: 'scale(' + lightboxZoom + ')' }" draggable="false" /></div>
      <p class="lightbox-help">{{ copy.zoomHelp }}</p>
    </div>

    <footer class="detail-footer"><div class="detail-shell">© 2026 FatCat Game Studio · {{ copy.madeIn }}</div></footer>
  </div>
</template>

<script>
import EventService from '@/services/EventService.js';
import { getInitialSiteLanguage } from '@/i18n/language';

const strings = {
  en: { back: 'All games', loading: 'Loading game details…', missing: 'This game could not be found.', googlePlay: 'Google Play', play: 'Play on itch.io', trailer: 'Watch trailer', privacy: 'Privacy policy', inside: 'Inside the game', features: 'What you can do', gallery: 'Gallery', galleryTitle: 'See the game in action', galleryHelp: 'Browse by platform, then open any image to view it up close.', filterMedia: 'Filter media by platform', allMedia: 'All', mobile: 'Mobile', web: 'Web', desktop: 'Desktop', console: 'Console', vr: 'VR', artwork: 'Artwork', openImage: 'Open image', closeImage: 'Close image', zoomIn: 'Zoom in', zoomOut: 'Zoom out', resetZoom: 'Reset zoom', zoomHelp: 'Pinch or use + / − to zoom. Scroll to explore the image.', gameplay: 'Gameplay', collage: 'Overview', art: 'Artwork', madeIn: 'Made with curiosity in Peru' },
  es: { back: 'Todos los juegos', loading: 'Cargando información…', missing: 'No encontramos este juego.', googlePlay: 'Google Play', play: 'Jugar en itch.io', trailer: 'Ver tráiler', privacy: 'Política de privacidad', inside: 'Dentro del juego', features: 'Qué puedes hacer', gallery: 'Galería', galleryTitle: 'Así se ve el juego', galleryHelp: 'Filtra por plataforma y abre cualquier imagen para verla en grande.', filterMedia: 'Filtrar imágenes por plataforma', allMedia: 'Todo', mobile: 'Móvil', web: 'Web', desktop: 'Escritorio', console: 'Consola', vr: 'VR', artwork: 'Arte', openImage: 'Ampliar imagen', closeImage: 'Cerrar imagen', zoomIn: 'Acercar', zoomOut: 'Alejar', resetZoom: 'Restablecer zoom', zoomHelp: 'Pellizca o usa + / − para ampliar. Desplázate para recorrer la imagen.', gameplay: 'Juego', collage: 'Resumen visual', art: 'Arte', madeIn: 'Hecho con curiosidad en Perú' }
};

export default {
  name: 'StudioGameDetail',
  data() {
    return { game: null, language: 'en', loading: true, activeMediaFilter: 'all', selectedMedia: null, lightboxZoom: 1, pinchStartDistance: 0, pinchStartZoom: 1, lightboxTrigger: null };
  },
  computed: {
    copy() { return strings[this.language]; },
    localized() {
      const locale = this.language === 'es' ? 'es-ES' : 'en-US';
      return this.game?.localized?.[locale] || this.game?.localized?.['en-US'] || {};
    },
    name() { return this.localized.name || this.game?.name || ''; },
    platforms() { return (this.game?.platforms || []).join(' · '); },
    mediaItems() {
      if (this.game?.media?.length) return this.game.media;
      return (this.game?.screenshots || []).map((url) => ({ url, platform: 'General', kind: 'artwork' }));
    },
    mediaFilters() {
      const groups = [...new Set(this.mediaItems.map((media) => this.mediaGroup(media)))];
      const labels = { mobile: this.copy.mobile, web: this.copy.web, desktop: this.copy.desktop, console: this.copy.console, vr: this.copy.vr, artwork: this.copy.artwork };
      return [{ id: 'all', label: this.copy.allMedia }, ...groups.map((id) => ({ id, label: labels[id] || this.copy.artwork }))];
    },
    visibleMedia() { return this.mediaItems.filter((media) => this.activeMediaFilter === 'all' || this.mediaGroup(media) === this.activeMediaFilter); },
    privacyRoute() {
      const routes = { mix2word: 'privacyMix2Word', pigYearFoodFight: 'privacyPigYear', lazyLovers: 'privacyLazyLovers', slothysPizzaMaster: 'privacyPizzaMaster', slothysBakery: 'privacySlothysBakery', slothysCafe: 'privacySlothysCafe', matchTheRunes: 'privacyMatchTheRunes' };
      const name = routes[this.game?.slug || this.game?.id];
      return name ? { name } : null;
    }
  },
  async created() {
    try {
      this.language = getInitialSiteLanguage();
    } catch (error) { this.language = 'en'; }
    try {
      const response = await EventService.getEvent(this.$route.params.id);
      this.game = response.data;
      document.title = `${this.localized.name || this.game.name} — FatCat Game Studio`;
      document.documentElement.lang = this.language;
    } catch (error) {
      this.game = null;
    } finally {
      this.loading = false;
    }
  },
  mounted() { window.addEventListener('keydown', this.handleWindowKeydown); },
  beforeDestroy() { window.removeEventListener('keydown', this.handleWindowKeydown); },
  methods: {
    mediaGroup(media) {
      if (media.kind === 'artwork') return 'artwork';
      if (media.platform === 'Android' || media.platform === 'iOS') return 'mobile';
      return ({ Web: 'web', Desktop: 'desktop', Console: 'console', VR: 'vr' })[media.platform] || 'artwork';
    },
    mediaPlatformLabel(platform) {
      const labels = { Android: 'Android · ' + this.copy.mobile, iOS: 'iOS · ' + this.copy.mobile, Web: this.copy.web, Desktop: this.copy.desktop, Console: this.copy.console, VR: this.copy.vr, General: this.copy.artwork };
      return labels[platform] || this.copy.artwork;
    },
    mediaKindLabel(kind) { return kind === 'gameplay' ? this.copy.gameplay : kind === 'collage' ? this.copy.collage : this.copy.art; },
    mediaLabel(media) { return `${this.mediaPlatformLabel(media.platform)} · ${this.mediaKindLabel(media.kind)}`; },
    openMedia(media, event) {
      this.lightboxTrigger = event?.currentTarget || null;
      this.selectedMedia = media;
      this.lightboxZoom = 1;
      this.$nextTick(() => this.$refs.lightbox?.focus());
    },
    closeMedia() {
      this.selectedMedia = null;
      this.lightboxZoom = 1;
      this.$nextTick(() => this.lightboxTrigger?.focus());
    },
    handleWindowKeydown(event) { if (this.selectedMedia && event.key === 'Escape') this.closeMedia(); },
    zoomBy(amount) { this.lightboxZoom = Math.min(3, Math.max(1, this.lightboxZoom + amount)); },
    wheelZoom(event) { if (this.selectedMedia) this.zoomBy(event.deltaY < 0 ? 0.15 : -0.15); },
    startPinch(event) {
      if (event.touches?.length === 2) {
        const dx = event.touches[0].clientX - event.touches[1].clientX;
        const dy = event.touches[0].clientY - event.touches[1].clientY;
        this.pinchStartDistance = Math.hypot(dx, dy);
        this.pinchStartZoom = this.lightboxZoom;
      }
    },
    movePinch(event) {
      if (event.touches?.length === 2 && this.pinchStartDistance) {
        const dx = event.touches[0].clientX - event.touches[1].clientX;
        const dy = event.touches[0].clientY - event.touches[1].clientY;
        this.lightboxZoom = Math.min(3, Math.max(1, this.pinchStartZoom * Math.hypot(dx, dy) / this.pinchStartDistance));
      }
    },
    toggleLanguage() {
      this.language = this.language === 'en' ? 'es' : 'en';
      try { localStorage.setItem('fatcat-site-language', this.language); } catch (error) { /* storage may be disabled */ }
      if (this.game) document.documentElement.lang = this.language;
    }
  }
};
</script>

